    def count_unique_characters(word):
        return len(set(word))

    max_word = ""
    max_unique_count = -1

    for word in words:
        unique_count = count_unique_characters(word)
        if (unique_count > max_unique_count) or \
           (unique_count == max_unique_count and word < max_word):
            max_unique_count = unique_count
            max_word = word

    return max_word

